using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Linq;

namespace TokenAuth
{
    public sealed class TokenPayload
    {
        public string Subject { get; set; }
        public long IssuedAt { get; set; }
        public long ExpiresAt { get; set; }
        public int PermissionBits { get; set; } // Signed: from JSON parsing
        public string Audience { get; set; }
    }

    public sealed class ResourceDescriptor
    {
        public string ResourceId { get; set; }
        public uint RequiredPermissions { get; set; } // Unsigned: bitmask
        public string Owner { get; set; }
        public int SensitivityLevel { get; set; }
    }

    public sealed class AuthorizationResult
    {
        public bool Granted { get; set; }
        public string Reason { get; set; }
        public string ResourceId { get; set; }
    }

    public interface ITokenSigner
    {
        byte[] Sign(byte[] payload);
        bool Verify(byte[] payload, byte[] signature);
    }

    public sealed class HmacTokenSigner : ITokenSigner
    {
        private readonly byte[] _key;

        public HmacTokenSigner(byte[] key)
        {
            if (key == null || key.Length < 32)
                throw new ArgumentException("Key must be at least 32 bytes");
            _key = new byte[key.Length];
            Array.Copy(key, _key, key.Length);
        }

        public byte[] Sign(byte[] payload)
        {
            using var hmac = new HMACSHA256(_key);
            return hmac.ComputeHash(payload);
        }

        public bool Verify(byte[] payload, byte[] signature)
        {
            var expected = Sign(payload);
            return CryptographicOperations.FixedTimeEquals(expected, signature);
        }
    }

    public sealed class TokenService
    {
        private readonly ITokenSigner _signer;
        private readonly HashSet<string> _revokedTokens = new();
        private readonly object _revocationLock = new();

        public TokenService(ITokenSigner signer)
        {
            _signer = signer ?? throw new ArgumentNullException(nameof(signer));
        }

        public (string token, byte[] signature) IssueToken(TokenPayload payload)
        {
            if (payload == null) throw new ArgumentNullException(nameof(payload));
            if (string.IsNullOrEmpty(payload.Subject))
                throw new ArgumentException("Subject required");

            // Reject the delimiter character in string fields to prevent
            // field-boundary injection in the serialized payload.
            if (payload.Subject.Contains('|'))
                throw new ArgumentException("Subject must not contain the '|' delimiter");
            if (payload.Audience != null && payload.Audience.Contains('|'))
                throw new ArgumentException("Audience must not contain the '|' delimiter");

            payload.IssuedAt = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            if (payload.ExpiresAt <= payload.IssuedAt)
                payload.ExpiresAt = payload.IssuedAt + 3600;

            // Reject negative permission bits at issuance
            if (payload.PermissionBits < 0)
                throw new ArgumentException("Permission bits must be non-negative");

            var tokenBytes = SerializePayload(payload);
            var signature = _signer.Sign(tokenBytes);
            var token = Convert.ToBase64String(tokenBytes);
            return (token, signature);
        }

        public TokenPayload ValidateToken(string token, byte[] signature)
        {
            if (string.IsNullOrEmpty(token) || signature == null)
                return null;

            byte[] tokenBytes;
            try { tokenBytes = Convert.FromBase64String(token); }
            catch { return null; }

            if (!_signer.Verify(tokenBytes, signature))
                return null;

            var payload = DeserializePayload(tokenBytes);
            if (payload == null) return null;

            // Check expiration
            var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            if (now > payload.ExpiresAt)
                return null;

            // Reject tokens with negative permission bits (invalid state)
            if (payload.PermissionBits < 0)
                return null;

            // Check revocation
            lock (_revocationLock)
            {
                if (_revokedTokens.Contains(token))
                    return null;
            }

            return payload;
        }

        public void RevokeToken(string token)
        {
            lock (_revocationLock)
            {
                _revokedTokens.Add(token);
            }
        }

        private byte[] SerializePayload(TokenPayload p)
        {
            var parts = $"{p.Subject}|{p.IssuedAt}|{p.ExpiresAt}|{p.PermissionBits}|{p.Audience}";
            return Encoding.UTF8.GetBytes(parts);
        }

        private TokenPayload DeserializePayload(byte[] data)
        {
            try
            {
                var parts = Encoding.UTF8.GetString(data).Split('|');
                if (parts.Length != 5) return null;
                return new TokenPayload
                {
                    Subject = parts[0],
                    IssuedAt = long.Parse(parts[1]),
                    ExpiresAt = long.Parse(parts[2]),
                    PermissionBits = int.Parse(parts[3]),
                    Audience = parts[4]
                };
            }
            catch { return null; }
        }
    }

    public sealed class PermissionEvaluator
    {
        // Permission constants
        public const uint PERM_READ = 0x01;
        public const uint PERM_WRITE = 0x02;
        public const uint PERM_DELETE = 0x04;
        public const uint PERM_ADMIN = 0x80000000; // High bit
        public const uint PERM_ALL = 0xFFFFFFFF;

        /// <summary>
        /// Checks if the token's permission bits satisfy the resource requirements.
        /// Uses bitwise AND to verify all required permission bits are set.
        /// </summary>
        public bool HasRequiredPermissions(TokenPayload token, ResourceDescriptor resource)
        {
            if (token == null || resource == null)
                return false;

            // Owner always has access to their own resources
            if (string.Equals(token.Subject, resource.Owner, StringComparison.Ordinal))
                return true;

            uint requiredBits = resource.RequiredPermissions;

            // Since ValidateToken already rejects negative PermissionBits,
            // the cast to uint is safe here (value is guaranteed non-negative)
            uint tokenBits = (uint)token.PermissionBits;

            // Check: do the token's bits cover all required bits?
            return (tokenBits & requiredBits) == requiredBits;
        }

        /// <summary>
        /// Validates that the permission level is sufficient for the sensitivity tier.
        /// Sensitivity levels: 0=public, 1=internal, 2=confidential, 3=restricted
        /// </summary>
        public bool MeetsSensitivityRequirement(TokenPayload token, ResourceDescriptor resource)
        {
            if (token == null || resource == null)
                return false;

            if (resource.SensitivityLevel == 0)
                return true; // Public resources need no special permissions

            // Since ValidateToken rejects negative PermissionBits, we know
            // token.PermissionBits >= 0, so casting to uint is safe.
            // However, PERM_ADMIN (0x80000000) can never be set in a non-negative int,
            // so admin bypass via this path requires explicit admin grant through
            // a separate mechanism (not shown here). This check is defense-in-depth.
            uint tokenBitsUnsigned = (uint)token.PermissionBits;
            if ((tokenBitsUnsigned & PERM_ADMIN) == PERM_ADMIN)
                return true;

            // For non-admin: count permission bits as a rough privilege level
            int bitCount = CountSetBits(tokenBitsUnsigned);
            return bitCount >= resource.SensitivityLevel;
        }

        private int CountSetBits(uint n)
        {
            int count = 0;
            while (n != 0) { count++; n &= n - 1; }
            return count;
        }
    }

    public sealed class AuthorizationService
    {
        private readonly TokenService _tokenService;
        private readonly PermissionEvaluator _permEvaluator;
        private readonly Dictionary<string, ResourceDescriptor> _resources = new();
        private readonly object _resourceLock = new();

        public AuthorizationService(TokenService tokenService, PermissionEvaluator permEvaluator)
        {
            _tokenService = tokenService;
            _permEvaluator = permEvaluator;
        }

        public void RegisterResource(ResourceDescriptor resource)
        {
            if (resource == null || string.IsNullOrEmpty(resource.ResourceId))
                throw new ArgumentException("Invalid resource");
            lock (_resourceLock)
            {
                _resources[resource.ResourceId] = resource;
            }
        }

        public AuthorizationResult Authorize(string token, byte[] signature, string resourceId)
        {
            if (string.IsNullOrEmpty(resourceId))
                return Deny(resourceId, "Invalid resource ID");

            var payload = _tokenService.ValidateToken(token, signature);
            if (payload == null)
                return Deny(resourceId, "Token validation failed");

            ResourceDescriptor resource;
            lock (_resourceLock)
            {
                if (!_resources.TryGetValue(resourceId, out resource))
                    return Deny(resourceId, "Resource not found");
            }

            // Check permission bits
            if (!_permEvaluator.HasRequiredPermissions(payload, resource))
                return Deny(resourceId, "Insufficient permissions");

            // Check sensitivity level
            if (!_permEvaluator.MeetsSensitivityRequirement(payload, resource))
                return Deny(resourceId, "Sensitivity requirement not met");

            return new AuthorizationResult
            {
                Granted = true,
                Reason = "Authorized",
                ResourceId = resourceId
            };
        }

        private AuthorizationResult Deny(string resourceId, string reason) =>
            new() { Granted = false, Reason = reason, ResourceId = resourceId };
    }
}
